package com.bank.monitor;

import java.util.concurrent.atomic.AtomicLong;

// What the application exposes at /actuator/prometheus. Counters only go up.
public class MetricEndpoint {
    private final AtomicLong transfersTotal = new AtomicLong();
    private final AtomicLong transfersFailed = new AtomicLong();

    public void recordTransfer(boolean success) {
        transfersTotal.incrementAndGet();
        if (!success) transfersFailed.incrementAndGet();
    }

    // A point-in-time snapshot of the counters — exactly what a scrape reads.
    public long totalSnapshot() { return transfersTotal.get(); }
    public long failedSnapshot() { return transfersFailed.get(); }
}
