package com.bank.monitor;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Prometheus PULLS: it reads the endpoint on each interval and stores a time-series.
public class PrometheusScraper {
    private static final Logger log = Logger.getLogger(PrometheusScraper.class.getName());

    private final MetricEndpoint target;
    // Each scrape stores a snapshot [total, failed] — an append-only time-series.
    private final List<long[]> series = new ArrayList<>();

    public PrometheusScraper(MetricEndpoint target) {
        this.target = target;
    }

    // One scrape = one HTTP GET of /actuator/prometheus.
    public void scrape() {
        long total = target.totalSnapshot();
        long failed = target.failedSnapshot();
        series.add(new long[]{total, failed});
        log.fine(() -> "SCRAPE: transfers_total=" + total + " transfers_failed=" + failed);
    }

    // PromQL-style error ratio computed from the rate over the last 'window' scrapes.
    public double errorRatioOverWindow(int window) {
        int n = series.size();
        if (n < 2) return 0.0;
        int startIdx = Math.max(0, n - 1 - window);
        long[] start = series.get(startIdx);
        long[] end = series.get(n - 1);
        long deltaTotal = end[0] - start[0];
        long deltaFailed = end[1] - start[1];
        return deltaTotal == 0 ? 0.0 : (double) deltaFailed / deltaTotal;
    }
}
