package com.bank.monitor;

import java.util.logging.Logger;

// An alert rule with a 'for' duration: fires only after the condition holds
// across enough consecutive evaluations. This is the key to avoiding false positives.
public class AlertRule {
    private static final Logger log = Logger.getLogger(AlertRule.class.getName());

    private final String name;
    private final double threshold;
    private final int forEvaluations;   // how many consecutive breaches before firing
    private int consecutiveBreaches = 0;
    private boolean firing = false;

    public AlertRule(String name, double threshold, int forEvaluations) {
        this.name = name;
        this.threshold = threshold;
        this.forEvaluations = forEvaluations;
    }

    // Called every evaluation interval with the current PromQL value.
    public void evaluate(double currentValue) {
        if (currentValue > threshold) {
            consecutiveBreaches++;
            if (consecutiveBreaches >= forEvaluations && !firing) {
                firing = true;
                log.severe(() -> "ALERT FIRING: " + name + " value=" + String.format("%.3f", currentValue)
                        + " > " + threshold + " for " + consecutiveBreaches
                        + " consecutive evals — PAGE on-call");
            } else if (!firing) {
                log.warning(() -> "PENDING: " + name + " breaching (" + consecutiveBreaches
                        + "/" + forEvaluations + ") — not yet paging (blip suppression)");
            }
        } else {
            if (consecutiveBreaches > 0) {
                log.info(() -> "RECOVERED: " + name + " back under threshold, resetting");
            }
            consecutiveBreaches = 0;
            firing = false;
        }
    }
}
