package com.bank.monitor;

import java.util.logging.*;

// Runnable demo: a 1-scrape blip is ignored; a sustained incident pages.
public class PrometheusDemo {
    private static final Logger log = Logger.getLogger(PrometheusDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Prometheus pull + alerting demo");

        MetricEndpoint endpoint = new MetricEndpoint();
        PrometheusScraper scraper = new PrometheusScraper(endpoint);
        // Alert if error ratio > 1% for 3 consecutive evaluations ('for' suppression).
        AlertRule rule = new AlertRule("HighTransferErrorRate", 0.01, 3);

        // Phase 1: healthy traffic — 100 successful transfers (Rajesh->Priya etc.)
        for (int i = 0; i < 100; i++) endpoint.recordTransfer(true);
        scraper.scrape();
        rule.evaluate(scraper.errorRatioOverWindow(1));

        // Phase 2: a ONE-scrape blip — 5 failures out of 100 (5% this window).
        log.info("-- one-scrape blip (transient network) --");
        for (int i = 0; i < 95; i++) endpoint.recordTransfer(true);
        for (int i = 0; i < 5; i++) endpoint.recordTransfer(false);
        scraper.scrape();
        rule.evaluate(scraper.errorRatioOverWindow(1));   // breach 1/3 — PENDING, no page

        // Phase 3: blip gone — next scrape healthy again. Counter resets.
        log.info("-- blip over, healthy scrape --");
        for (int i = 0; i < 100; i++) endpoint.recordTransfer(true);
        scraper.scrape();
        rule.evaluate(scraper.errorRatioOverWindow(1));   // recovered

        // Phase 4: a SUSTAINED incident — 3 consecutive bad windows.
        log.info("-- sustained incident (downstream account svc degraded) --");
        for (int w = 0; w < 3; w++) {
            for (int i = 0; i < 90; i++) endpoint.recordTransfer(true);
            for (int i = 0; i < 10; i++) endpoint.recordTransfer(false);
            scraper.scrape();
            rule.evaluate(scraper.errorRatioOverWindow(1));
        }
    }
}
